// All four commands are WebView-facing — the reconciliation pass that drives
// them (`runReminderPass`) is TypeScript, so the WebView is the caller. They are
// therefore listed here and `tauri_plugin::Builder` autogenerates their
// `allow-*` / `deny-*` permissions under `permissions/autogenerated/`, which the
// deny-by-default `reminders:default` set then grants as a group.
//
// `ios_path` wires the `ios/` Swift package into the generated Xcode project;
// `android_path` emits `cargo:android_library_path=…` so the app's `tauri-build`
// auto-includes `android/` in the generated gradle project
// (`gen/android/tauri.settings.gradle`). Each is inert off its own target.
const COMMANDS: &[&str] = &[
    "schedule",
    "cancel",
    "cancel_all",
    "list_pending",
    "permission_status",
    "request_permission",
    "exact_alarm_status",
    "request_exact_alarm",
];

fn main() {
    tauri_plugin::Builder::new(COMMANDS)
        .ios_path("ios")
        .android_path("android")
        .build();
}
